import os


class DocFileHandler:
    """
    This is a class that handles Word documents and provides functionalities for reading, writing, and modifying the content of Word documents.
    """

    def __init__(self, file_path):
        """
        Initializes the DocFileHandler object with the specified file path.
        :param file_path: str, the path to the Word document file.
        """
        self.file_path = file_path

    def read_text(self):
        """
        Reads the content of a Word document and returns it as a string.
        :return: str, the content of the Word document.
        """
        try:
            doc = Document(self.file_path)
            content = []
            for paragraph in doc.paragraphs:
                content.append(paragraph.text)
            return '\n'.join(content)
        except Exception:
            return ""

    def write_text(self, content, font_size=12, alignment='left'):
        """
        Writes the specified content to a Word document.
        :param content: str, the text content to write.
        :param font_size: int, optional, the font size of the text (default is 12).
        :param alignment: str, optional, the alignment of the text ('left', 'center', or 'right'; default is 'left').
        :return: bool, True if the write operation is successful, False otherwise.
        """
        try:
            if os.path.exists(self.file_path):
                doc = Document(self.file_path)
            else:
                doc = Document()

            paragraph = doc.add_paragraph(content)
            paragraph.alignment = self._get_alignment_value(alignment)

            for run in paragraph.runs:
                run.font.size = Pt(font_size)

            doc.save(self.file_path)
            return True
        except Exception:
            return False

    def add_heading(self, heading, level=1):
        """
        Adds a heading to the Word document.
        :param heading: str, the text of the heading.
        :param level: int, optional, the level of the heading (1, 2, 3, etc.; default is 1).
        :return: bool, True if the heading is successfully added, False otherwise.
        """
        try:
            if os.path.exists(self.file_path):
                doc = Document(self.file_path)
            else:
                doc = Document()

            doc.add_heading(heading, level)
            doc.save(self.file_path)
            return True
        except Exception:
            return False

    def add_table(self, data):
        """
        Adds a table to the Word document with the specified data.
        :param data: list of lists, the data to populate the table.
        :return: bool, True if the table is successfully added, False otherwise.
        """
        try:
            if not data or not isinstance(data, list) or len(data) == 0:
                return False

            if os.path.exists(self.file_path):
                doc = Document(self.file_path)
            else:
                doc = Document()

            rows = len(data)
            cols = len(data[0]) if data[0] else 0

            if cols == 0:
                return False

            table = doc.add_table(rows=rows, cols=cols)

            for i, row_data in enumerate(data):
                row_cells = table.rows[i].cells
                for j, cell_data in enumerate(row_data):
                    if j < len(row_cells):
                        row_cells[j].text = str(cell_data)

            doc.save(self.file_path)
            return True
        except Exception:
            return False

    def _get_alignment_value(self, alignment):
        """
        Returns the alignment value corresponding to the given alignment string.
        :param alignment: str, the alignment string ('left', 'center', or 'right').
        :return: int, the alignment value.
        """
        alignment_map = {
            'left': WD_PARAGRAPH_ALIGNMENT.LEFT,
            'center': WD_PARAGRAPH_ALIGNMENT.CENTER,
            'right': WD_PARAGRAPH_ALIGNMENT.RIGHT
        }
        return alignment_map.get(alignment.lower(), WD_PARAGRAPH_ALIGNMENT.LEFT)

class IPAddress:
    """
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    """

    def __init__(self, ip_address):
        """
        Initialize the IP address to the specified address
        :param ip_address:string
        """
        self.ip_address = ip_address


    def is_valid(self):
        """
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: bool
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.is_valid()
        True
        """
        if not isinstance(self.ip_address, str):
            return False

        parts = self.ip_address.split('.')

        if len(parts) != 4:
            return False

        for part in parts:
            if not part:
                return False

            # Check if part contains only digits
            if not part.isdigit():
                return False

            # Check for leading zeros (except for "0" itself)
            if len(part) > 1 and part[0] == '0':
                return False

            # Convert to integer and check range
            try:
                num = int(part)
                if num < 0 or num > 255:
                    return False
            except ValueError:
                return False

        return True


    def get_octets(self):
        """
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: list
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_octets()
        ["10", "10", "10", "10"]
        """
        if self.is_valid():
            return self.ip_address.split('.')
        else:
            return []


    def get_binary(self):
        """
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: string
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_binary()
        "00001010.00001010.00001010.00001010"
        """
        if self.is_valid():
            octets = self.get_octets()
            binary_octets = []

            for octet in octets:
                # Convert to integer then to binary, remove '0b' prefix and pad to 8 bits
                binary = format(int(octet), '08b')
                binary_octets.append(binary)

            return '.'.join(binary_octets)
        else:
            return ''

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        """
        if not string:
            return string

        result = []
        i = 0

        while i < len(string):
            if i < len(string) - 2 and string[i:i+2] == '&#':
                # Found start of numeric entity
                start = i
                i += 2

                # Check if it's hexadecimal (&#x or &#X)
                is_hex = False
                if i < len(string) and string[i].lower() == 'x':
                    is_hex = True
                    i += 1

                # Extract the numeric part
                num_start = i
                while i < len(string) and string[i] != ';':
                    if is_hex:
                        if not self.is_hex_char(string[i]):
                            break
                    else:
                        if not string[i].isdigit():
                            break
                    i += 1

                # Check if we found a valid entity (ends with semicolon)
                if i < len(string) and string[i] == ';' and i > num_start:
                    num_str = string[num_start:i]
                    try:
                        if is_hex:
                            char_code = int(num_str, 16)
                        else:
                            char_code = int(num_str, 10)

                        # Convert to character and add to result
                        result.append(chr(char_code))
                        i += 1  # Skip the semicolon
                    except (ValueError, OverflowError):
                        # Invalid number, add original text
                        result.append(string[start:i+1])
                        i += 1
                else:
                    # Not a valid entity, add original text
                    result.append(string[start:i])
            else:
                result.append(string[i])
                i += 1

        return ''.join(result)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True

        """
        return char.lower() in '0123456789abcdef'

class Words2Numbers:
    """
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    """

    def __init__(self):
        """
        Initialize the word lists and dictionaries required for conversion
        """
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        if not textnum:
            return "0"

        # Handle negative numbers
        textnum = textnum.strip().lower()
        negative = False
        if textnum.startswith('negative') or textnum.startswith('minus'):
            negative = True
            textnum = textnum.replace('negative', '').replace('minus', '').strip()

        # Handle ordinal numbers
        textnum = self._convert_ordinals(textnum)

        # Replace hyphens with spaces and split
        words = textnum.replace('-', ' ').split()

        current = result = 0

        for word in words:
            if word in self.numwords:
                scale, increment = self.numwords[word]

                if scale > 1:
                    if scale > 100:
                        result += current * scale
                        current = 0
                    else:  # scale == 100
                        current *= scale
                else:
                    current += increment
            elif word == "and":
                continue
            else:
                # Invalid word, return "0" or handle as needed
                return "0"

        result += current

        if negative:
            result = -result

        return str(result)

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        False
        """
        if not textnum:
            return False

        textnum = textnum.strip().lower()

        # Remove negative/minus prefix
        if textnum.startswith('negative') or textnum.startswith('minus'):
            textnum = textnum.replace('negative', '').replace('minus', '').strip()

        # Convert ordinals to check validity
        textnum = self._convert_ordinals(textnum)

        # Replace hyphens with spaces and split
        words = textnum.replace('-', ' ').split()

        # Check if all words are valid number words
        for word in words:
            if word not in self.numwords and word != "and":
                return False

        return True

    def _convert_ordinals(self, text):
        """
        Convert ordinal words to their cardinal equivalents
        """
        words = text.split()
        converted_words = []

        for word in words:
            # Check direct ordinal mappings
            if word in self.ordinal_words:
                # Convert to cardinal form
                cardinal_num = self.ordinal_words[word]
                cardinal_word = self.units[cardinal_num] if cardinal_num < len(self.units) else str(cardinal_num)
                converted_words.append(cardinal_word)
            else:
                # Check ordinal endings
                converted = False
                for ending, replacement in self.ordinal_endings:
                    if word.endswith(ending):
                        cardinal_word = word[:-len(ending)] + replacement
                        if cardinal_word in self.numwords or cardinal_word == "":
                            if cardinal_word == "":
                                # Handle cases like "twentieth" -> "twenty"
                                base_word = word[:-len(ending)]
                                if base_word + "y" in self.numwords:
                                    converted_words.append(base_word + "y")
                                else:
                                    converted_words.append(word)
                            else:
                                converted_words.append(cardinal_word)
                            converted = True
                            break

                if not converted:
                    converted_words.append(word)

        return " ".join(converted_words)
